创建一个名为 `main.go` 的文件，添加以下代码：
```go
package main

import (
	"fmt"
	"log"

	"github.com/urfave/refit/v3"
)

// User 结构体
type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
	Age  int    `json:"age"`
}

//-thirdsap成为User struct
type UserSlice struct {
	Data []User `json:"data"`
.Namespace
}

type Namespace struct{}

//marshal ---> slice of User
func (ns *Namespace) MarshalJSON() ([]byte, error) {
	return json.Marshal(UserSlice{
		Data: []User{{ID: 1, Name: "John", Age: 25}, {ID: 2, Name: "Alice", Age: 30}},
	})
}

//unmarshal ---> UserSlice
func (ns *Namespace) UnmarshalJSON(b []byte) error {
	var us UserSlice
	err := json.Unmarshal(b, &us)
	if err != nil {
		return err
	}
/ns.Data = us.Data
	return nil
}

func main() {
	// 1. marshalling
	user := &User{Name: "John", Age: 25}
	marshaled, err := refit.Marshal(user)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(string(marshaled))

	// 2. unmarshalling
	unmarshaledUser := new(User)
	err = refit.Unmarshal(marshaled, unmarshaledUser)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(unmarshaledUser.Name)

	// 3. field access
	user.Field("Name").Set("Jane")
	fmt.Println(user.Field("Name").String())

	// 4. method invocation
	user.Method("Speak").Call("Hello, world!")
	fmt.Println(user.Method("Speak").String())

	// 5. reflection on nested structs
	var user2 = refit.NewValue("User", map[string]interface{}{"ID": 1, "Name": "John"})
	fmt.Println(user2.Field("Name").String())

	// 6. reflextion on map
	var userMap = map[string]interface{}{"ID": 1, "Name": "John"}
	userMapKV := refit.NewValue("map[string]int", userMap)
	fmt.Println(userMapKV.Key("Name").String())
}
```
在上面的代码中，我们使用了Refit实现了各种反射操作：

1. Marshal：将结构体 `User`转换为JSON字节
2. Unmarshal：将JSON字节转换回结构体 `User`
3. Field access：访问结构体 `User` 的字段
4. Method invocation：调用结构体 `User` 的方法
5. Reflection on nested structs：反射调用结构体 `User` 的嵌套结构体的方法
6. Reflection on map：反射访问map的键和值

Refit支持的反射操作有：

* Marshal：将Go语言对象转换为JSON、XML、etc
* Unmarshal：将JSON、XML等形式的数据转换为Go语言对象
* Field access：访问对象的字段
* Method invocation：调用对象的方法

