// Shared data structure
struct Data {
    int value;
};

int main() {
    // Initialize named mutex
    boost::interprocess::named_mutex mutex("my_mutex");

    // Initialize named semaphore
    boost::interprocess::named_semaphore sem("my_semaphore", 0);

    // Initialize shared memory
    boost::interprocess::managed_shared_memory segment(boost::interprocess::open_or_create, "my_heap", 1024);
    Data* pdata = segment.construct<Data>("my_data")(0);

    // Initialize message queue
    boost::interprocess::message_queue queue(boost::interprocess::open_or_create, "my_queue", 10, sizeof(int));

    // Producer loop
    for (int i = 0; i < 10; i++) {
        // Acquire mutex
        mutex.lock();
        pdata->value = i;
        std::cout << "Produced: " << pdata->value << std::endl;
        mutex.unlock();

        // Signal semaphore
        sem.post());

        // Send message to queue
        boost::interprocess::message_queue::size_type size;
        boost::interprocess::message.rmi_queue(boost::interprocess::for_write_only_t).send(msg, size);

        // Sleep for a bit
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
