const int N = 1000; // количество разбиений_INTERVAL suitable for integration
const double h = 1.0 / N; // шаг разбиения
const int MAX_THREADS = 4; // количество потоков

double f(double x) {
    return x * exp(-x); // функция для интегрирования
}

double rectangleMethod(int numThreads) {
    double integral = 0;
    HANDLE sem = CreateSemaphore(NULL, 0, numThreads, NULL);
    for (int i = 0; i < N; i++) {
        double x = i * h;
        integral += f(x);
        releaseSemaphore(sem);
    }
    WaitForMultipleObjects(numThreads, &sem, TRUE, INFINITE);
    CloseHandle(sem);
    return integral * h;
}

double trapezoidalMethod(int numThreads) {
    double integral = 0;
    HANDLE sem = CreateSemaphore(NULL, 0, numThreads, NULL);
    for (int i = 0; i < N; i++) {
        double x1 = (i * h);
        double x2 = (i + 1) * h;
        integral += 0.5 * (f(x1) + f(x2)) * h;
        releaseSemaphore(sem);
    }
    WaitForMultipleObjects(numThreads, &sem, TRUE, INFINITE);
    CloseHandle(sem);
    return integral;
}

double simpsonMethod(int numThreads) {
    double integral = 0;
    HANDLE sem = CreateSemaphore(NULL, 0, numThreads, NULL);
    for (int i = 0; i < N; i++) {
        double x1 = (i * h);
        double x2 = (i + 1) * h;
        if (i % 2 == 0) {
            integral += f(x1);
        } else {
            integral += 2 * f(x2);
        }
        releaseSemaphore(sem);
    }
    WaitForMultipleObjects(numThreads, &sem, TRUE, INFINITE);
    CloseHandle(sem);
    return (h / 3) * (integral + f(0) + f(N * h));
}

double approximatingIntegral(int numThreads, HANDLE sem) {
    double integral = 0;
    for (int i = 0; i < N; i++) {
        double x = (i * h);
        integral += f(x);
        releaseSemaphore(sem);
        Sleep(1000); // остановка на 1 секунду для иллюстрации работы потоков
    }
    WaitForSingleObject(sem, INFINITE);
    return integral * h;
}

void threadFunc(void* arg) {
    int numThreads = *((int*)arg);
    HANDLE sem = CreateSemaphore(NULL, 0, numThreads, NULL);
    double integral = approximatingIntegral(numThreads, sem);
    releaseSemaphore(sem);
    CloseHandle(sem);
    printf("Thread %d finished with integral = %f\n", numThreads, integral);
}

int main() {
    HANDLE threads[MAX_THREADS];
    HANDLE sem = CreateSemaphore(NULL, 0, MAX_THREADS, NULL);
    int numThreads;
    srand(time(0)); // инициализация случайного генератора
    for (int i = 0; i < MAX_THREADS; i++) {
        numThreads = i + 1;
        threads[i] = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)threadFunc, &numThreads, 0, NULL);
    }
    WaitForMultipleObjects(MAX_THREADS, threads, TRUE, INFINITE);
    printf("All threads finished\n");
    CloseHandle(sem);
    return 0;
}
