// Clase para representar un nodo del árbol binario
class Node {
public:
    int valor;
    Node* izquierda;
    Node* derecha;
};

// Clase para representar el árbol binario
class BinarySearchTree {
public:
    Node* raiz; // puntero al node raíz del árbol

    // Constructor para inicializar el árbol binario vacío
    BinarySearchTree() {
        raiz = nullptr;
    }

    // Función para insertar un nodo en el árbol
    void insertar(int valor) {
        Node* nuevo = new Node;
        nuevo->valor = valor;
        nuevo->izquierda = nullptr;
        nuevo->derecha = nullptr;

        if (raiz == nullptr) {
            raiz = nuevo;
        } else {
            Node* actual = raiz;
            while (true) {
                if (valor < actual->valor) {
                    if (actual->izquierda == nullptr) {
                        actual->izquierda = nuevo;
                        return;
                    }
                    actual = actual->izquierda;
                } else {
                    if (actual->derecha == nullptr) {
                        actual->derecha = nuevo;
                        return;
                    }
                    actual = actual->derecha;
                }
            }
        }
    }

    // Función para buscar un valor en el árbol
    Node* buscar(int valor) {
        Node* actual = raiz;
        while (actual != nullptr) {
            if (valor == actual->valor) {
                return actual;
            } else if (valor < actual->valor) {
                actual = actual->izquierda;
            } else {
                actual = actual->derecha;
            }
        }
        return nullptr; // valor no encontrado
    }
};

int main() {
    BinarySearchTree árbol;
    árbol.insertar(5);
    árbol.insertar(3);
    árbol.insertar(7);
    árbol.insertar(2);
    árbol.insertar(4);
    árbol.insertar(6);
    árbol.insertar(8);

    Node* resultado = árbol.buscar(4);
    if (resultado != nullptr) {
        std::cout << "Valor encontrado: " << resultado->valor << std::endl;
    } else {
        std::cout << "Valor no encontrado" << std::endl;
    }

    return 0;
}
