import heapq

class Node:
    def __init__(self, name):
        self.name = name
        self.distance = float('inf')
        self.parent = None

class FibonacciHeap:
    def __init__(self):
        self.nodes = []

    def insert_or_update(self, node):
        for n in self.nodes:
            if n.name == node.name:
                heapq.heappop(self.nodes)
        heapq.heappush(self.nodes, node)

