      main: '#ff9800',
    },
  },
});

class GoogleOAuth extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isLoggedIn: false,
      userData: null,
    };
  }

  handleSignIn = () => {
    const provider = new GoogleAuthProvider();
    signInWithPopup(provider)
      .then((result) => {
        this.setState({
          isLoggedIn: true,
          userData: result.user.providerData[0],
        });
      })
      .catch((error) => {
        console.error(error);
      });
  };

  handleSignOut = () => {
    this.setState({
      isLoggedIn: false,
      userData: null,
    });
  };

  render() {
    return (
      <MuiThemeProvider theme={theme}>
        <div>
          {this.state.isLoggedIn ? (
            <div>
              <Typography variant="h6">
                Welcome, {this.state.userData.displayName}!
              </Typography>
              <Button variant="contained" color="secondary" onClick={this.handleSignOut}>
                Sign out
              </Button>
            </div>
          ) : (
            <Button variant="contained" color="primary" onClick={this.handleSignIn}>
              Sign in with Google
            </Button>
          )}
        </div>
